phase58Root = pwd;
phase58Model = 'phase58_model';
phase58ModelPath = fullfile(phase58Root, [phase58Model '.slx']);
phase58ResultPath = fullfile(phase58Root, 'result.json');
assert(~isfile(phase58ModelPath), '目标模型已存在，请先检查现有文件。');
