add_block('simulink/Math Operations/Gain', [phase58Model '/Gain'], 'Gain', '4', 'Position', [200 85 260 135]);
add_block('simulink/Sinks/Display', [phase58Model '/Display'], 'Position', [345 90 440 130]);
add_line(phase58Model, 'Constant/1', 'Gain/1', 'autorouting', 'on');
add_line(phase58Model, 'Gain/1', 'Display/1', 'autorouting', 'on');
set_param(phase58Model, 'SolverType', 'Fixed-step', 'Solver', 'FixedStepDiscrete', 'FixedStep', '0.1', 'StartTime', '0', 'StopTime', '1', 'SignalLogging', 'on', 'SignalLoggingName', 'logsout', 'SaveTime', 'on', 'TimeSaveName', 'tout', 'ReturnWorkspaceOutputs', 'on');
phase58GainPorts = get_param([phase58Model '/Gain'], 'PortHandles');
set_param(phase58GainPorts.Outport, 'DataLogging', 'on', 'DataLoggingNameMode', 'Custom', 'DataLoggingName', 'gainOutput');
set_param(phase58Model, 'ZoomFactor', 'FitSystem');
save_system(phase58Model, phase58ModelPath);
drawnow;
