assert(all(phase58Data(:) == 12), 'Display 输入不符合预期值 12。');
assert(abs(phase58Simulation.tout(end) - 1) < 1e-12, '仿真未达到指定终止时间。');
phase58Result = struct('displayedValue', double(phase58Data(end)));
% 将仿真测得的数值写入用户指定的 JSON 文件。
phase58Json = jsonencode(phase58Result);
phase58Fid = fopen(phase58ResultPath, 'w');
assert(phase58Fid >= 0, '无法写入 result.json。');
phase58FileCleanup = onCleanup(@() fclose(phase58Fid));
fprintf(phase58Fid, '%s\n', phase58Json);
clear phase58FileCleanup;
save_system(phase58Model, phase58ModelPath);
assert(isfile(phase58ModelPath), '模型文件未保存。');
phase58Readback = jsondecode(fileread(phase58ResultPath));
assert(phase58Readback.displayedValue == phase58Result.displayedValue, 'JSON 文件回读校验失败。');
fprintf('模型已保存: %s\n仿真已完成: StopTime=1, Solver=FixedStepDiscrete, FixedStep=0.1\nresult.json: %s\n', phase58ModelPath, phase58Json);

